## Goal of this PR

Adds the formation resource:
```
resource "gamefabric_formation" "this" {

  name        = var.name
  environment = data.ec_core_environment_v1.this.id
  labels      = var.labels

  description = var.description
  volume_templates = [
    {
      name              = volume_template.key
      reclaim_policy    = volume_template.value.reclaim_policy
      volume_store_name = volume_template.value.volume_store_name
      capacity          = volume_template.value.capacity
    }
  ]

  vessels = [
    {
      name        = try(vessel.key)
      region      = try(vessel.value.region)
      description = try(vessel.value.description, "")
      suspend     = try(vessel.value.suspended, false) # if not set the field should be ignored and make gamefabric authoritive of the state
      override = {
        #profiling_enabled = var.profiling_enabled # they might want to profile only single vessels
        labels            = local.template_labels
        containers = [
          {

            command = ["example-command"]
            args    = ["example-arg"]
            envs = [
              {
                name  = "EXAMPLE_ENV"
                value = "example_value"
              },
              {
                name = "EXAMPLE_CONFIG_FILE"
                value_from = {
                  config_file = "example_config_file"
                }
              },
              {
                name = "EXAMPLE_POD_FIELD"
                value_from = {
                  # is apiVersion really needed here?
                  field_path = "metadata.name" # can we somehow define all the allowed keys here? Does this make sense?
                }
              }
            ]
            # no security_context, this is on purpose
          }
        ]
      }
    }
  ]


  gameserver_labels      = local.template_labels      #the ones that will end up on the pod
  gameserver_annotations = local.template_annotations #the ones that will end up on the pod


  // Containers
  containers = [
    {
      name = "example-container"
      image = {
        name   = "gameserver-asoda0s" # this is the name of the image object, not the image itself
        branch = "prod"               # this is the branch of the image, not the
      }
      command = ["example-command"]
      args    = ["example-arg"]
      resources = {
        limits = {
          cpu    = "500m"
          memory = "512Mi"
        }
        requests = {
          cpu    = "250m"
          memory = "256Mi"
        }
      }
      envs = [
        {
          name  = "EXAMPLE_ENV"
          value = "example_value"
        },
        {
          name = "EXAMPLE_CONFIG_FILE"
          value_from = {
            config_file = "example_config_file"
          }
        },
        {
          name = "EXAMPLE_POD_FIELD"
          value_from = {
            # is apiVersion really needed here?
            field_path = "metadata.name" # can we somehow define all the allowed keys here? Does this make sense?
          }
        }
      ]
      ports = [
        {
          name                = "http"
          protocol            = "TCP"
          container_port      = 8080
          policy              = "Passthrough" # or "Dynamic"
          protection_protocol = "something"   # optional
        }
      ]
      volume_mounts = [
        {
          name          = "example-volume"
          mount_path    = "/data"
          sub_path      = "subdir" # optional. maybe remove it even
          sub_path_expr = "expr"   # optional. maybe remove it even
          # no mount_propagation, read_only, recursive_read_only etc.
        }
      ]
      config_files = [
        {
          name       = "example-config-file"
          mount_path = "/config/example-config-file" # where the config file will be mounted in the container
        }
      ]
      # no security_context, this is on purpose
    }
  ]

  // Agones Health Checks

  health_checks = {
    disabled              = !var.enable_health_checks
    initial_delay_seconds = var.health_check_initial_delay_seconds
    period_seconds        = var.health_check_period_seconds
    failure_threshold     = var.health_check_failure_threshold
  }



  // Termination Grace Period
  termination_configuration = { # optional, applies to all vessels
    grace_period_seconds   = var.termination_grace_period_seconds
    maintenance_seconds    = var.maintenance_seconds
    spec_change_seconds    = var.spec_change_seconds
    user_initiated_seconds = var.user_initiated_seconds
  }

  // Volumes
  volumes = [
    {
      # this format and structure to be the same as in formations
      name = "emptydir-volume"
      empty_dir = {
        size_limit = "1Gi"
      }
      # for formations there will be more possible types, and only one of them can be defined at a time
    },
    {
      # this format and structure to be the same as in formations
      name = "persistent-volume"
      persistent = {
        volume_name = var.volume_name
      }
      # for formations there will be more possible types, and only one of them can be defined at a time
    }
  ]
  gateway_policies  = var.gateway_policy_names
  profiling_enabled = var.profiling_enabled # set correct label in the background, maybe api change?
}



# resource "vessel_state" "name" {
#   vessel_name = gamefabric_formation_v1beta1.this.vessels[0].name
#   suspend     = false # or "Suspended", "Terminating", etc.
#   # this is just an example, you can use any state you want
#   # the vessel_state resource is used to update the state of the vessel in the formation
# }
```

## How did I test it?

Manually and unit tests.
